L=[['拉丁 cīvis','公民；共同生活在一个城邦中的人']]
CV=L+[['拉丁 cīvīlis → 古法语 civil；拉丁也有直接借入影响','公民、公共生活有关的；合宜有礼的'],['中古英语 civil → 现代英语 civil','民事、公民生活相关的；有礼的']]
CI=L+[['拉丁 cīvitās／cīvitātem','公民身份 → 公民共同体'],['古法语 citet／cité → 中古英语 cite → 英语 city','共同体所在的地方 → 城市']]
CZ=L+[['拉丁 cīvitās → 古法语 cité','公民共同体 → 城市'],['古法语 citeien；盎格鲁法语 citesein／citezein','城镇中的居民'],['中古英语 citisein → 英语 citizen','城镇居民 → 国家公民']]
CK=L+[['拉丁 cīvicus → 英语 civic','与公民、城市公共生活有关的']]
CE=L+[['拉丁 cīvīlis → 法语 civil → civiliser','公民生活相关的 → 使有礼、使形成文明生活'],['英语 civilize／civilise','使行为合宜；旧时所谓使文明化']]
CN=L+[['拉丁 cīvīlis → 法语 civil → civiliser → civilisation','公共生活 → 文明化的过程与状态'],['英语 civilization／civilisation','文明；一个社会的整体文化与生活方式']]
CT=L+[['拉丁 cīvīlis → cīvīlitās；古法语 civilité','公民性质、身份 → 合宜的公共行为'],['英语 civility','待人有礼；基本的尊重和客气']]
W=[
E('civil','/ˈsɪvəl/','公民生活的；民事的；非军事的；有礼的','大家共同生活，需要制度，也需要彼此给对方一点体面。','接拉丁 cīvīlis，由 cīvis“公民”形成；经古法语及拉丁直接借入。这里 -il 不是 ill“生病”。',CV,'civil war 是一国内部的战争；civil rights 是公民权利；civil case 是民事案件；a civil reply 是不失礼的回答。几个义项都从社会生活展开，必须看后面搭配，不能一律翻译成“文明”。','civil society；civil rights；civil engineering；keep the discussion civil。','civic 多指城市或公民公共责任；civil 的范围更广。civil engineer 是土木工程师，不能理解为“有礼貌的工程师”。',('We disagreed, but the conversation remained civil.','我们意见不同，但谈话始终保持礼貌。'),('The dispute became a civil case.','这场纠纷成了一起民事案件。'),('She works as a civil engineer on bridge projects.','她是一名土木工程师，参与桥梁项目。'),sources=['https://www.etymonline.com/word/civil','https://www.oxfordlearnersdictionaries.com/definition/english/civil']),
E('civilian','/səˈvɪliən/','平民；非军人的；民用的','把普通社会生活中的人和军队等制服体系区分开。','借古法语 civilien，接 civil／拉丁 cīvīlis。现代可用 civil + -ian 记形；历史上先指民法专家，后来发展为普通非军事人员。',L+[['拉丁 cīvīlis → 古法语 civilien → 中古英语 cyvylien','民法相关的 → 民法专业人员'],['英语 civilian','后来常指非军事人员；也用于民用性质的事物']],'a civilian 是平民；civilian clothes 是便服；civilian aircraft 是民用飞机。一般语境常与军人或警务人员对照；它不是“有国籍的人”的同义词。','civilian life；civilian clothes；a civilian employee；civilian aircraft。','citizen 说一个人与国家的公民身份关系；civilian 说是否属于军事等特定体系。军人也可以是 citizen。',('After leaving the army, he found civilian life unfamiliar.','离开军队后，他对平民生活感到陌生。'),('The airfield handles both military and civilian aircraft.','这座机场同时处理军用和民用飞机的起降。'),sources=['https://www.etymonline.com/word/civilian','https://www.oxfordlearnersdictionaries.com/definition/english/civilian_1']),
E('civilization','英 /ˌsɪvəlaɪˈzeɪʃən/；美 /ˌsɪvələˈzeɪʃən/','文明；某一文明社会；有组织的生活环境','把一个社会的制度、城市、知识、技术和生活方式放在一起看。','现代可拆 civilize + -ation；常用社会文化义与法语 civilisation 的借入有关。英语另有较早的法律用法，不宜把所有义项都画成一次简单派生。',CN,'ancient civilizations 说古代不同文明；the development of civilization 说文明发展。口语 back to civilization 常是离开偏远处，回到有交通、商店等设施的生活环境。这个词不能简化成“人人都有礼貌”。','ancient civilization；the rise of civilization；a centre of civilization；back to civilization。','culture 更常说一个群体的价值、习俗和表达方式；civilization 常从历史尺度看整个社会的组织与成就，两者范围会重叠。',('The exhibition compares the writing systems of several ancient civilizations.','展览比较了几种古代文明的文字系统。'),('After a week in the mountains, they joked that they were returning to civilization.','在山里待了一周后，他们开玩笑说终于要回到文明世界了。'),sources=['https://www.etymonline.com/word/civilization','https://en.wiktionary.org/wiki/civilization#English']),
E('civilisation','英 /ˌsɪvəlaɪˈzeɪʃən/；美 /ˌsɪvələˈzeɪʃən/','文明；文明社会〔civilization 的拼写变体〕','一整套社会生活发展起来：有人组织公共事务，也有知识和文化传承。','对应 civilisation 的 -s- 拼写，常见于英式英语；与 civilization 同源同义，不是另一种文明。可按 civilise + -ation 看形式。',CN[:-1]+[['英语 civilisation；与 civilization 并行的拼写','文明及其社会形态']],'a history of civilisation 是文明史。写作时 civilise、civilised、civilisation 可保持同一套拼写；英式英语也允许 -ize 系列，不能据一个 z 就判为美式。','ancient civilisation；industrial civilisation；the history of civilisation。','civilisation 是社会层面的文明；civility 是交往中的客气。一个社会的物质成就与一个人的礼貌不是同一概念。',('The course explores the history of civilisation through everyday objects.','课程通过日常器物探索文明史。'),('Trade connected this civilisation with communities beyond the mountains.','贸易把这个文明与山外的群体连接起来。'),sources=['https://en.wiktionary.org/wiki/civilisation#English','https://www.etymonline.com/word/civilization']),
E('civic','/ˈsɪvɪk/','公民的；城市公共事务的；市民责任方面的','把眼光从“我家的事”移到“我们共同生活的地方”。','直接接拉丁 cīvicus，由 cīvis“公民”派生；不是英语 civil 换一个尾巴才首次产生的词。',CK,'civic duty 是公民责任；civic pride 是对所在城市或社区的自豪感；a civic centre 常是公共服务或活动中心。重点在共同体的公共生活。','civic engagement；civic duty；civic pride；civic leaders。','civic 通常不表示一个人待人客气；要说客气，用 civil 或 polite。civil war 也不能换成 civic war。',('The clean-up project strengthened their sense of civic pride.','清理环境的项目增强了他们对社区的自豪感。'),('The school encourages civic engagement through local volunteer projects.','学校通过当地志愿项目鼓励学生参与公共事务。'),sources=['https://www.etymonline.com/word/civic']),
E('civility','/sɪˈvɪləti/','礼貌；客气；文明有礼的态度','即使不喜欢对方，也让对方把话说完，不用羞辱回应分歧。','接拉丁 cīvīlitās，经法语 civilité 等来源进入英语；现代可按 civil + -ity 理解名词结构，不能当作唯一借入历史。',CT,'treat someone with civility 是以基本尊重待人。复数 exchange civilities 常说互相寒暄；这些客套未必表示双方关系亲密。','basic civility；a lack of civility；with civility；exchange civilities。','civility 强调不失礼的基本底线；warmth 强调热情。一个人可以很客气，却显得疏远。',('They discussed the disagreement with surprising civility.','他们出人意料地客客气气地讨论了分歧。'),('We exchanged a few civilities before turning to the main issue.','我们寒暄了几句，然后转入正题。'),sources=['https://www.etymonline.com/word/civility','https://en.wiktionary.org/wiki/civility#English']),
E('civilly','/ˈsɪvəli/','客气地；有礼地；在民事方面','把话说得体面，不把不满直接变成冲撞。','civil + -ly；形容一种处事或说话方式，也可对应 civil 的民事法律义。',CV+[['英语 civil + -ly → civilly','有礼地；在民事方面']],'reply civilly 常是礼貌但未必亲热地回答。法律文字中的 civilly liable 则是民事责任方面的表达，不能译成“礼貌地负责”。','reply civilly；speak civilly；treat someone civilly；civilly liable。','politely 是更通用的“有礼貌地”；civilly 有时隐含克制住不友好的情绪，至少保留基本礼节。',('She answered civilly despite the impatient tone of the question.','虽然提问的语气不耐烦，她仍客气地回答。'),('The neighbours learned to speak civilly to one another again.','邻居们又学会了客客气气地对话。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/civilly','https://en.wiktionary.org/wiki/civilly#English']),
E('uncivil','/ʌnˈsɪvəl/','无礼的；粗鲁的','一句话也许没骂人，却明显把对方应有的体面拿走了。','un-“不” + civil“有礼的”；否定的是礼貌义，不表示“不是民事的”。',CV+[['英语 un- + civil → uncivil','待人不客气、无礼的']],'an uncivil remark 是无礼的话；an uncivil tone 是粗鲁的语气。这是对行为和态度的评价，常见于较正式叙述。','an uncivil reply；an uncivil remark；an uncivil tone。','uncivil 比 uncivilized 更集中于言语、礼节；后者还可能评价整体行为是否粗野。',('His uncivil reply ended the conversation.','他无礼的回答让谈话就此结束。'),('You can challenge an idea without making an uncivil remark.','你可以反驳观点，而不说无礼的话。'),sources=['https://en.wiktionary.org/wiki/uncivil#English','https://www.etymonline.com/word/uncivil']),
E('incivility','/ˌɪnsɪˈvɪləti/','无礼；粗鲁的言行','把小小的不尊重表现出来：打断、挖苦、冷冷地羞辱别人。','借法语 incivilité，接后期拉丁 incīvīlitās，由否定 in- + cīvīlis 一支派生。现代可对应 in- + civility，但不是只在英语里加前缀的历史。',L+[['拉丁 in- + cīvīlis → incīvīlis → 后期拉丁 incīvīlitās','不合礼的 → 无礼'],['法语 incivilité → 英语 incivility','粗鲁态度或一件失礼行为']],'workplace incivility 是工作场所里失礼、不尊重的行为；复数 incivilities 可指一件件小冒犯。它不一定达到暴力或违法的程度。','workplace incivility；online incivility；an act of incivility；a pattern of incivility。','incivility 评价交往态度；illegality 说违法。失礼与违法不是同一条界线。',('The team leader addressed the growing incivility in meetings.','组长处理了会议中日益增多的无礼言行。'),('Small incivilities can gradually damage a working relationship.','一次次小小的失礼会逐渐破坏工作关系。'),sources=['https://www.etymonline.com/word/incivility','https://en.wiktionary.org/wiki/incivility#English']),
E('civilizational','英 /ˌsɪvəlaɪˈzeɪʃənəl/；美 /ˌsɪvələˈzeɪʃənəl/','文明层面的；不同文明之间的','把讨论尺度拉大到社会的历史、制度与思想传统。','civilization + -al；指与文明相关，而不是“更有礼貌”。',CN+[['英语 civilization + -al → civilizational','文明社会及其历史传统层面的']],'civilizational change 说长期、广泛的文明变化；civilizational differences 说文明之间的差异。多用于历史、社会和政治讨论，日常描述一个人礼貌无需用它。','civilizational change；civilizational differences；civilizational exchange。','civilized 是行为有礼、生活有组织等评价；civilizational 是“关于文明”的关系形容词，本身不作好坏判断。',('The historian traces civilizational change across several centuries.','历史学家追踪了几个世纪里的文明变化。'),('The article examines trade as a form of civilizational exchange.','文章把贸易作为文明交流的一种形式来研究。'),sources=['https://www.merriam-webster.com/dictionary/civilizational','https://en.wiktionary.org/wiki/civilizational#English']),
E('civilize','/ˈsɪvəlaɪz/','使更有礼、更有秩序；使文明化','让相处方式少一点粗暴、多一点规则和体谅。','借法语 civiliser，由 civil 形成使动词；现代对应 civil + -ize。历史上的“使文明化”常夹带说话者对别人社会的等级判断。',CE,'civilize a debate 可指让争论摆脱辱骂。历史文献谈 civilize a people 时，常是在声称改变别人整个生活方式；读这种句子要分清作者的立场与事实。','civilize a debate；a civilizing influence；attempt to civilize。','educate 是教育、传授知识；civilize 还带行为、秩序或所谓文明程度的评价，不能把二者机械互换。',('Clear rules helped civilize the debate.','明确的规则让辩论变得更文明有序。'),('The historian questions the claim that one people can “civilize” another.','历史学家质疑一个民族能够“教化”另一个民族的说法。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/civilize','https://www.etymonline.com/word/civilize']),
E('civilise','/ˈsɪvəlaɪz/','使举止更文明；使文明化〔civilize 的拼写变体〕','把相互冲撞的场面变得有规则、有分寸。','与 civilize 同一个动词，-ise 是常见英式拼写；法语来源是 civiliser。不要把 -ise 看成不同的词根。',CE[:-1]+[['英语 civilise；civilize 的拼写变体','使行为更有礼、更有秩序']],'civilise 的过去式是 civilised。它可以带幽默语气，如用一杯茶让紧张的谈话缓和；写历史上的殖民“教化”叙事时则含明显的价值立场。','civilise the discussion；a civilising influence；civilise behaviour。','organise 只说组织安排；civilise 往往还评价行为是否体面。会议有议程，未必就没有辱骂。',('They hoped a neutral chair would civilise the discussion.','他们希望一位中立的主持人能让讨论更文明。'),('She joked that a cup of tea might civilise the morning meeting.','她开玩笑说，一杯茶也许能让晨会变得文明些。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/civilize','https://en.wiktionary.org/wiki/civilise#English']),
E('civilized','/ˈsɪvəlaɪzd/','有礼而理性的；文明的；舒适体面的','有分歧也好好说话，日子过得有秩序、有体面。','civilize + -ed；原为过去分词，也成为形容词。后者可直接描述状态，不一定在讲某人曾经被“教化”。',CE+[['英语 civilize + -ed → civilized','文明有礼的；有组织、舒适体面的']],'a civilized conversation 是讲理、不互相攻击的谈话；a civilized breakfast 可幽默地说一顿从容舒适的早餐。用于划分民族文明高低时，带有历史上的价值判断。','a civilized conversation；civilized behaviour；a civilized society；a civilized hour。','civil 常只要求基本客气；civilized 可进一步强调理性、体面与舒适。a civilized hour 是不太早或太晚的合适时间。',('We finally managed to have a civilized conversation about the problem.','我们终于能心平气和地谈这个问题了。'),('Let’s meet at a more civilized hour tomorrow.','明天我们换个更合适的时间见面吧。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/civilized']),
E('civilised','/ˈsɪvəlaɪzd/','文明有礼的；舒适体面的〔civilized 的拼写变体〕','既把事情办好，也让参与的人过得舒服、不受粗暴对待。','civilise + -ed；英式常见拼写，与 civilized 读音、核心意义相同。',CE[:-1]+[['英语 civilise + -ed → civilised','文明有礼的；从容舒适的']],'civilised behaviour 可以形容在压力下仍讲理；civilised surroundings 可指舒适、便利、适合安稳相处的环境。它不只是夸装修漂亮。','civilised behaviour；a civilised discussion；civilised surroundings。','sophisticated 常说复杂精致或见识广；civilised 更关注有礼、讲理和生活体面，两者不相等。',('The two sides kept the discussion civilised.','双方让讨论保持文明有礼。'),('We ate in civilised surroundings instead of rushing on the platform.','我们在舒适的环境里吃了饭，没有在站台上匆忙将就。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/civilized','https://en.wiktionary.org/wiki/civilised#English']),
E('uncivilized','/ʌnˈsɪvəlaɪzd/','粗野失礼的；不文明的','把别人的感受和共同生活的规则都抛到一边。','un-“不” + civilized；通常否定文明有礼的行为，也出现在旧时对社会发展程度的评价中。',CE+[['英语 civilized → un- + civilized → uncivilized','文明有礼的 → 粗野、不文明的']],'uncivilized behaviour 是强烈批评，如抢夺、羞辱或毫无体谅的做法。把一个民族整体叫 uncivilized 带有贬低意味；现代阅读要看是谁在这样评价。','uncivilized behaviour；an uncivilized response；an uncivilized way to behave。','uncivil 常指一言一行不客气；uncivilized 的评价通常更重、范围更广。两者都不等于“教育程度低”。',('Pushing past people in the queue is uncivilized behaviour.','在队伍里推开别人往前挤，是不文明的行为。'),('The narrator exposes the prejudice behind the label “uncivilized”.','叙述者揭示了“不文明”这一标签背后的偏见。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/uncivilized','https://en.wiktionary.org/wiki/uncivilized#English']),
E('uncivilised','/ʌnˈsɪvəlaɪzd/','粗野的；不文明的〔uncivilized 的拼写变体〕','面对分歧时只顾攻击，不肯守住基本的体面。','un- + civilised；保留 -s- 的英式拼写，含义与 uncivilized 相同。',CE[:-1]+[['英语 civilise → civilised → uncivilised','使有礼 → 有礼的 → 不文明、粗野的']],'an uncivilised argument 是充满粗鲁攻击的争吵。它是带批评态度的词；形容陌生社会时，可能暴露说话者把自己的生活方式当作唯一标准。','uncivilised conduct；uncivilised behaviour；an uncivilised argument。','unfamiliar 只说不熟悉；uncivilised 则作负面评价。不熟悉某种习俗，并不等于它粗野。',('The moderator stopped the uncivilised argument.','主持人制止了这场粗野的争吵。'),('The essay challenges the old description of those communities as uncivilised.','文章质疑过去把那些群体称为“不文明”的描述。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/uncivilized','https://en.wiktionary.org/wiki/uncivilised#English']),
E('city','/ˈsɪti/','城市；都市；城市政府或居民〔依语境〕','最初看的是共同生活的一群公民，后来名字落到了他们居住的地方。','经古法语 cité 接拉丁 cīvitās／cīvitātem，由 cīvis“公民”形成。拼写里失去 v，是法语演变的一部分；不能拆成英语 ci + ty。',CI,'a busy city 是繁忙都市；the city announced ... 常借“城市”指市政府。city centre 是市中心。不同地方对 city 的正式称号规定不同，不要把它固定等于某个人口门槛。','a capital city；the city centre；city life；the city council。','town 通常比 city 小，但正式地位与日常大小不总一致；urban 是“城市的”形容词。',('The river runs through the centre of the city.','河流穿过城市中心。'),('The city has opened a new public library.','市政府开设了一座新的公共图书馆。'),sources=['https://www.etymonline.com/word/city','https://en.wiktionary.org/wiki/city#English']),
E('citizen','/ˈsɪtɪzən/','公民；城市居民；市民','不是临时路过，而是这个共同体中具有成员身份的人。','经盎格鲁法语 citesein／citezein，接古法语 cité“城市”一支；更早是拉丁 cīvis → cīvitās。现代并没有一个能自由使用的 -zen“人”后缀。',CZ,'a citizen of a country 常说法律上的国家公民；a concerned citizen 常说关心公共事务的市民或公民。senior citizen 是较委婉的老年人称呼。','a citizen of；a concerned citizen；a private citizen；a senior citizen。','resident 强调住在哪里；citizen 强调成员、公民身份。住在一个国家的人不一定拥有该国公民身份。',('She is a citizen of Canada and currently lives abroad.','她是加拿大公民，目前住在国外。'),('Concerned citizens asked for a safer crossing near the school.','关心公共事务的市民要求在学校附近设置更安全的过街设施。'),sources=['https://www.etymonline.com/word/citizen','https://en.wiktionary.org/wiki/citizen#English']),
E('citizenship','/ˈsɪtɪzənʃɪp/','公民身份；公民资格；公民责任与参与','成为共同体成员，不只是一个称号，也涉及权利、责任和参与。','citizen + -ship；这里 -ship 表身份、状态或关系，与船 ship 的独立名词义无关。',CZ+[['英语 citizen + -ship → citizenship','公民的身份及相应责任、参与']],'apply for citizenship 是申请公民身份；citizenship education 是学习公共责任、权利和社会参与。第二种用法更关注如何做共同体成员，不只是办理证件。','apply for citizenship；acquire citizenship；dual citizenship；citizenship education。','nationality 常指法律国籍，也可能涉及民族身份；citizenship 重点在公民身份及其权利义务，具体语境里不能总作完全同义。',('He applied for citizenship after living there for many years.','在那里生活多年后，他申请了公民身份。'),('The school links citizenship education with community projects.','学校把公民教育与社区项目结合起来。'),sources=['https://www.etymonline.com/word/citizenship','https://en.wiktionary.org/wiki/citizenship#English']),
E('citizenry','/ˈsɪtɪzənri/','全体公民；全体市民','不点名其中一个人，而是把整个公民群体放进视野。','citizen + -ry；-ry 在这里形成集合名词，表示一群具有同一身份的人。',CZ+[['英语 citizen + -ry → citizenry','全体公民作为一个群体']],'an informed citizenry 是掌握信息、有判断能力的公民群体。常见于公共政策、新闻和社会讨论，语气比 citizens 正式一些；它不是公民资格。','an informed citizenry；an active citizenry；the local citizenry。','citizenship 是身份、资格或公民责任；citizenry 是人群。不要把后者当作前者的抽象名词变体。',('Reliable local news helps build an informed citizenry.','可靠的地方新闻有助于形成知情的公民群体。'),('The council invited the citizenry to comment on the new plan.','市议会邀请全体市民对新计划发表意见。'),sources=['https://www.etymonline.com/word/citizenry','https://www.oxfordlearnersdictionaries.com/definition/english/citizenry']),
E('civics','/ˈsɪvɪks/','公民学；公民教育课程','学习公共机构怎么运转，以及普通成员有哪些权利、责任和参与方式。','由 civic 形成，仿照 politics 等学科名使用 -ics。结尾 s 属于学科名称，不是在数多个 civic。',CK+[['英语 civic → civics','公民公共事务 → 公民学、相关课程']],'a civics class 可讲政府结构、公共决策、权利与责任。作为一门课程或学科时通常配单数动词，如 civics is ...。','a civics class；a civics lesson；teach civics；a civics textbook。','civics 侧重公民如何理解和参与公共生活；political science 是范围更广的政治学研究，两者相关但不是同一课程名称。',('Our civics class discussed how local decisions are made.','我们的公民课讨论了地方决策是怎样作出的。'),('Civics is part of the school’s social studies programme.','公民学是学校社会科课程的一部分。'),sources=['https://www.etymonline.com/word/civics','https://en.wiktionary.org/wiki/civics#English'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0227')
ROOT=[dict(id='C0227',meaning='公民；共同生活的成员',core='civ- = citizen：一起生活，就有共同的事务与相处规则。',image='想象一座城：city 是大家生活的地方，citizen 是其中的成员，civic 关心公共事务，civil 也关心人与人怎样相处。',intro='拉丁 cīvis 指公民或城邦成员。它分出 cīvīlis“公民生活相关的”和 cīvicus“公民、城市公共事务的”，又形成 cīvitās“公民共同体”；后者经法语演变成 city。礼貌义来自“合乎共同生活的行为”这条延伸，不是所有含 civ- 的词都在夸人文明。',forms='civil-、civic- 保留较清楚的拉丁形状；city、citizen 经法语变化，表面已经没有 v。civilize／civilise、civilization／civilisation 是并行拼写，不是两套词源。',branches=[['成员与生活的地方','city、citizen、citizenship、citizenry'],['公共事务与普通社会生活','civil、civilian、civic、civics'],['相处的基本礼貌','civility、civilly、uncivil、incivility'],['文明及行为评价','civilization、civilisation、civilizational、civilize、civilise、civilized、civilised、uncivilized、uncivilised']],contrasts='civilian 说是否属于军队等体系，citizen 说公民身份；civil 可指客气，civic 通常不指客气。civility 是交往礼貌，civilization 是社会文明，不能因为近形就互译。',practice='把一座城市的三件事分别说出来：一个 citizen 参与 civic activity，并且与意见不同的人保持 civil。再用 citizenry 说人群，用 citizenship 说身份。',words=list(family),exclude={},sources=['https://www.etymonline.com/word/civil','https://www.etymonline.com/word/city','https://www.etymonline.com/word/citizen'])]
assert {x['word'] for x in W}==set(family)
